
## Claude adapted these from my own functions that are in , in order to generate the main figures .  

## This file requires that naturalMods2 (the list of final models) exists
## That is generated by the obesityanalysis.R file.

getContrasts <- function(i, modslist) {
  emmeans(modslist[[i]], ~Group, type = "response",
          at = list(age = 12, sex = "Male", ethgr5 = "White"),
          data = modslist[[i]]$survey.design$variables) |>
    contrast("trt.vs.ctrl", adjust = "none") |>
    as.data.frame() |> as.data.table()
}

# Allows you to provide an adjusted p-value to use instead of the internal model p-values
# p_char is whether we use p= or q=
makeObesityGraph2_QVAL <- function(i, modslist, padj = NULL,pchar="q") {
  emgrid <- emmeans(modslist[[i]], ~Group, type = "response",
                    at = list(age = 12, sex = "Male", ethgr5 = "White"),
                    data = modslist[[i]]$survey.design$variables)
  plotdat <- emgrid |> contrast("trt.vs.ctrl", adjust = "none", infer = c(TRUE, TRUE)) |>
    as.data.frame() |> as.data.table()
  plotdat[, c("group1", "group2") := tstrsplit(gsub("[()]", "", contrast), " / ")]
  
  # swap in the externally adjusted p-values, matched by contrast name
  if (!is.null(padj)) {
    plotdat[padj, p.value := i.p.adj, on = "contrast"]
  }
  
  plotdat2 <- emgrid |> as.data.frame() |> as.data.table()
  height <- max(plotdat2$upper.CL) - min(plotdat2$lower.CL)
  plotdat[, ypos := max(plotdat2$upper.CL) + height * (1:.N) / 10]
  plotdat[, p.label := ifelse(p.value < 0.001, sprintf("%s<0.001",pchar), sprintf("%s=%0.3f", pchar,p.value))]
  
  ggplot(plotdat2) +
    aes(x = Group, y = response, ymin = lower.CL, ymax = upper.CL) +
    geom_errorbar(width = 0.2) + geom_point() +
    ggpubr::stat_pvalue_manual(data = plotdat, y.position = "ypos",
                               label = "p.label", size = 3.5) +
    theme_bw() +
    labs(x = "BMI SDS Group", y = labelsvector3b[names(modslist)[i]])
}

makeLargeModelsFigure <- function(modslist){

  allcon <- rbindlist(lapply(seq_along(modslist), getContrasts, modslist = modslist),
                      idcol = "model")
  allcon[, p.adj := p.adjust(p.value, method = "BH")]
  
  modplots <-seq_along(modslist) |> lapply( \(i) 
      makeObesityGraph2_QVAL(i, modslist, padj = allcon[model == i, .(contrast, p.adj)])) |> 
      setNames(names(modslist))
  
  modplots[order_of_outputs] |> wrap_plots(ncol = 5) + 
    plot_layout(axis_titles = "collect") & 
    scale_x_discrete(labels=c("NDNS <85th centile","NDNS 85th-95th centile","NDNS >95th centile","GOOS")) &   
    scale_y_continuous(expand = expansion(0.1)) &
    theme(axis.text.x=element_text(angle=20,hjust=1)) &
    theme(plot.margin = margin(l = 20,t=10,r=10,b = 10, unit = "pt"))

}

makeLargeModelsFigure(naturalMods2[order_of_outputs2])
ggsave(filename = file.path("oct26figs","obeseGraph3_main_qvals.png"),
       width=14,height=14,dpi="retina")

