ggsave(filename = file.path("oct26figs","IMD_obeseGraph3_main_qvals.png"),
       width=14,height=14,dpi="retina")


#eqv_mods_year_noGroup

###### THE SAME LOGIC FOR THE INCOME ANALYSES

getIncomeContrasts <- function(i, modslist) {
  emmeans(modslist[[i]], ~eqv3F, type = "response",
          data = modslist[[i]]$survey.design$variables) |>
    contrast("pairwise", adjust = "none") |>
    as.data.frame() |> as.data.table()
}

makeIncomeGraph_QVAL <- function(i, modslist, padj = NULL,pchar="q") {
  emgrid <- emmeans(modslist[[i]], ~eqv3F, type = "response",
                    data = modslist[[i]]$survey.design$variables)
  plotdat <- emgrid |> contrast("pairwise", adjust = "none", infer = c(TRUE, TRUE)) |>
    as.data.frame() |> as.data.table()
  plotdat[, c("group1", "group2") := tstrsplit(contrast, " / ")]
  
  # swap in the externally adjusted p-values, matched by contrast name
  if (!is.null(padj)) {
    plotdat[padj, p.value := i.p.adj, on = "contrast"]
  }
  
  plotdat2 <- emgrid |> as.data.frame() |> as.data.table()
  height <- max(plotdat2$upper.CL) - min(plotdat2$lower.CL)
  plotdat[, ypos := max(plotdat2$upper.CL) + height * c(0.2, 0.6, 0.4)]
  plotdat[, p.label := ifelse(p.value < 0.001, sprintf("%s<0.001",pchar), sprintf("%s=%0.3f", pchar,p.value))]
  
  ggplot(plotdat2) +
    aes(x = eqv3F, y = response, ymin = lower.CL, ymax = upper.CL) +
    geom_errorbar(width = 0.2) + geom_point() +
    ggpubr::stat_pvalue_manual(data = plotdat, y.position = "ypos", label = "p.label") +
    theme_bw() +
    labs(x = "Income tertile", y = labelsvector3b[names(modslist)[i]])
}

makeLargeModelsFigure_INCOME <- function(modslist){

  inccon <- rbindlist(lapply(seq_along(modslist), getIncomeContrasts, modslist = modslist),
                      idcol = "model")
  inccon[, p.adj := p.adjust(p.value, method = "BH")]
  
  modplots <-seq_along(modslist) |> lapply( \(i) 
    makeIncomeGraph_QVAL(i, modslist, padj = inccon[model == i, .(contrast, p.adj)])) |>
    setNames(names(modslist))
  
  modplots[order_of_outputs] |> wrap_plots(ncol = 5) + 
    plot_layout(axes="collect",guides="collect") & 
    scale_x_discrete(labels=c("High","Mid","Low")) & 
    scale_y_continuous(expand = expansion(0.1))
  
}



